#!/usr/bin/env bash
# Supplied output check; students do not edit this file.
set -u
program="$1"
expected="$2"
actual="$(mktemp)"
trap 'rm -f "$actual"' EXIT
echo "LOCAL CHECK: $(basename "$expected")"
if "$program" > "$actual"; then
    cat "$actual"
    if diff -u "$expected" "$actual"; then
        echo "PASS $(basename "$expected")"
        exit 0
    fi
    echo "FAIL $(basename "$expected")"
    exit 1
fi
cat "$actual"
echo "FAIL $(basename "$expected"): program did not finish normally"
exit 1
